BEGIN;

CREATE TABLE public.products (
    id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    sku varchar(40) NOT NULL,
    name varchar(200) NOT NULL,
    price numeric(12,2) NOT NULL,
    CONSTRAINT pk_products PRIMARY KEY (id),
    CONSTRAINT uq_products_sku UNIQUE (sku)
);

CREATE TABLE public.customers (
    id uuid NOT NULL,
    name varchar(120) NOT NULL,
    email varchar(254) NULL,
    is_deleted boolean NOT NULL DEFAULT false,
    CONSTRAINT pk_customers PRIMARY KEY (id)
);

CREATE TABLE public.notes (
    id uuid NOT NULL,
    entity_type varchar(32) NOT NULL,
    entity_id varchar(40) NOT NULL,
    body text NOT NULL,
    created_at timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_notes PRIMARY KEY (id)
);
CREATE INDEX ix_notes_entity_type_entity_id ON public.notes (entity_type, entity_id);

CREATE TABLE public.payments (
    id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    kind varchar(32) NOT NULL,
    amount numeric(12,2) NOT NULL,
    reference varchar(64) NULL,
    CONSTRAINT pk_payments PRIMARY KEY (id)
);
COMMENT ON TABLE public.payments IS 'Every payment, one row each, with its type code in kind; a card payment adds a row in card_payments.';

CREATE TABLE public.card_payments (
    payment_id bigint NOT NULL,
    last4 varchar(4) NOT NULL,
    CONSTRAINT pk_card_payments PRIMARY KEY (payment_id),
    CONSTRAINT fk_card_payments_payment FOREIGN KEY (payment_id) REFERENCES public.payments (id) ON DELETE CASCADE
);
COMMENT ON TABLE public.card_payments IS 'What a card payment adds to its payments row: one row per card payment, keyed by the payment''s id.';

CREATE TABLE public.corporate_card_payments (
    payment_id bigint NOT NULL,
    cost_center varchar(32) NOT NULL,
    CONSTRAINT pk_corporate_card_payments PRIMARY KEY (payment_id),
    CONSTRAINT fk_corporate_card_payments_card_payment FOREIGN KEY (payment_id) REFERENCES public.card_payments (payment_id) ON DELETE CASCADE
);
COMMENT ON TABLE public.corporate_card_payments IS 'What a corporate card payment adds to its card_payments row.';

CREATE TABLE public.quotes (
    id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    number varchar(20) NOT NULL,
    billing_street varchar(120) NOT NULL,
    billing_city varchar(80) NOT NULL,
    billing_delivery_notes jsonb NULL,
    billing_latitude numeric(9,6) NULL,
    billing_longitude numeric(9,6) NULL,
    CONSTRAINT pk_quotes PRIMARY KEY (id)
);
COMMENT ON TABLE public.quotes IS 'One row per quote, with its billing address in columns: the map point in two columns, the courier notes as JSON.';

CREATE TABLE public.quote_shipping_addresses (
    quote_id bigint NOT NULL,
    street varchar(120) NOT NULL,
    city varchar(80) NOT NULL,
    delivery_notes jsonb NULL,
    geo jsonb NULL,
    CONSTRAINT pk_quote_shipping_addresses PRIMARY KEY (quote_id),
    CONSTRAINT fk_quote_shipping_addresses_quote FOREIGN KEY (quote_id) REFERENCES public.quotes (id) ON DELETE CASCADE
);
COMMENT ON TABLE public.quote_shipping_addresses IS 'A quote''s shipping address, at most one row per quote; the map point is JSON.';

CREATE TABLE public.quote_notes (
    quote_id bigint NOT NULL,
    position integer NOT NULL,
    text varchar(500) NOT NULL,
    author varchar(80) NULL,
    CONSTRAINT pk_quote_notes PRIMARY KEY (quote_id, position),
    CONSTRAINT fk_quote_notes_quote FOREIGN KEY (quote_id) REFERENCES public.quotes (id) ON DELETE CASCADE
);
COMMENT ON TABLE public.quote_notes IS 'A quote''s notes, one row per note, in order.';

CREATE TABLE public.quote_labels (
    id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    quote_id bigint NOT NULL,
    label varchar(40) NOT NULL,
    CONSTRAINT pk_quote_labels PRIMARY KEY (id),
    CONSTRAINT fk_quote_labels_quote FOREIGN KEY (quote_id) REFERENCES public.quotes (id)
);
COMMENT ON TABLE public.quote_labels IS 'A quote''s labels, one row each with an id of its own; the foreign key does not cascade, so a delete removes the labels first.';

COMMIT;
